package com.jadhavr.erp.academic.controller;
import com.jadhavr.erp.academic.enums.AcademicStatus; import com.jadhavr.erp.academic.repository.StudentSectionEnrollmentRepository; import com.jadhavr.erp.academic.service.AcademicService; import com.jadhavr.erp.auth.security.SecurityUtils; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.common.exception.ResourceNotFoundException; import com.jadhavr.erp.student.repository.StudentProfileRepository; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/student/academic") public class StudentAcademicController { private final StudentProfileRepository students;private final StudentSectionEnrollmentRepository enrollments;private final AcademicService service;public StudentAcademicController(StudentProfileRepository s,StudentSectionEnrollmentRepository e,AcademicService a){students=s;enrollments=e;service=a;} private com.jadhavr.erp.student.entity.StudentProfile me(){return students.findByUserId(SecurityUtils.requireCurrentUser().getId()).orElseThrow(()->new ResourceNotFoundException("Student profile not found"));} @GetMapping("/timetable") public ApiResponse<?> timetable(){var e=enrollments.findFirstByStudentAndStatus(me(),AcademicStatus.ACTIVE).orElseThrow(()->new ResourceNotFoundException("Student is not assigned to a section"));return ApiResponse.success("My timetable",service.timetable(e.getSection().getId()));} @GetMapping({"/attendance","/attendance/summary"}) public ApiResponse<?> attendance(){return ApiResponse.success("My attendance",service.attendanceSummary(me().getId()));}}
